package com.vignesh.focuslist.ui.component

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The Today mascot for a day whose work is finished: the cat sitting, content.
 *
 * A sitting pose like the Inbox cat, and the difference is the eyes: closed and
 * curved where the Inbox cat's are open and waiting. It marks the end of a day
 * that had work in it, which is why Today draws it only when something was
 * actually completed. See D-033.
 *
 * Exported from the board, node `1068:5746`. It takes the same scale factor as
 * the other four. [MascotImage] explains why the paths are built in Kotlin and
 * which colour role each tone takes.
 *
 * Its nose takes [mid] rather than [dark], the same exception the Inbox cat
 * makes: both sitting poses are drawn with a nose lighter than their eyes.
 */
@Composable
internal fun AllDoneMascot(modifier: Modifier = Modifier) {
    MascotImage(
        width = MascotWidth,
        height = MascotHeight,
        modifier = modifier,
        build = ::catSittingHappy
    )
}

private const val MascotWidth = 195.43f
private const val MascotHeight = 175.84f

private fun catSittingHappy(light: Color, mid: Color, dark: Color): ImageVector =
    ImageVector.Builder(
        name = "AllDoneCatSittingHappy",
        defaultWidth = MascotWidth.dp,
        defaultHeight = MascotHeight.dp,
        viewportWidth = 536.454f,
        viewportHeight = 482.675f
    )
        .addPath(
            pathData = addPathNodes(GroundShadow),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Body),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Shading),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(EarShading),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Nose),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(EyeLeft),
            fill = SolidColor(dark)
        )
        .addPath(
            pathData = addPathNodes(EyeRight),
            fill = SolidColor(dark)
        )
        .build()

